const input = $input.first().json;
const body = input.body || input;

const possibleQuestionLists = [
  body.questions,
  body.answers,
  body.submission?.questions,
  body.submission?.answers,
  body.data?.questions,
  body.data?.answers
].filter(Boolean);

const questions = possibleQuestionLists[0] || [];

function normalizeValue(value) {
  if (Array.isArray(value)) {
    return value.map(v => {
      if (v && typeof v === "object") {
        return v.url || v.fileUrl || v.downloadUrl || v.value || JSON.stringify(v);
      }
      return v;
    }).join(", ");
  }

  if (value && typeof value === "object") {
    return value.email || value.url || value.fileUrl || value.downloadUrl || value.value || value.text || value.answer || JSON.stringify(value);
  }

  return value || "";
}

function getQuestion(label) {
  return questions.find(q => {
    const name = q.name || q.label || q.title || q.question || q.id || "";
    return name.toLowerCase().trim() === label.toLowerCase().trim();
  });
}

function getAnswer(label) {
  const found = getQuestion(label);
  if (!found) return "";

  return normalizeValue(
    found.value ??
    found.answer ??
    found.response ??
    found.text ??
    ""
  );
}

function getFile(label) {
  const found = getQuestion(label);

  if (!found) {
    return {
      url: "",
      filename: ""
    };
  }

  const value = found.value;

  if (Array.isArray(value) && value.length > 0) {
    return {
      url: value[0]?.url || value[0]?.fileUrl || value[0]?.downloadUrl || "",
      filename: value[0]?.filename || value[0]?.name || ""
    };
  }

  if (value && typeof value === "object") {
    return {
      url: value.url || value.fileUrl || value.downloadUrl || "",
      filename: value.filename || value.name || ""
    };
  }

  return {
    url: typeof value === "string" ? value : "",
    filename: ""
  };
}

const attachment = getFile("Ekran Görüntüsü / Dosya");
const audio = getFile("Sesli Açıklama");

return [
  {
    json: {
      name: getAnswer("Ad Soyad"),
      email: getAnswer("Email"),
      product_page: getAnswer("Ürün / Sayfa Adı"),
      title: getAnswer("Bug Başlığı"),
      description: getAnswer("Bug Açıklaması"),
      steps: getAnswer("Tekrar Etme Adımları"),
      expected_result: getAnswer("Beklenen Sonuç"),
      actual_result: getAnswer("Gerçekleşen Sonuç"),
      device_browser: getAnswer("Cihaz/Tarayıcı"),

      attachment_url: attachment.url,
      attachment_filename: attachment.filename,

      audio_url: audio.url,
      audio_filename: audio.filename,

      transcript: "",

      raw_body: body
    }
  }
];

const formData = $node["Normalize Form Data"].json;

return [
  {
    json: {
      ...formData,
      transcript: ""
    }
  }
];

const formData = $("Normalize Form Data").first().json;
const groqResult = $input.first().json;

const transcript =
  groqResult.text ||
  groqResult.transcription ||
  groqResult.data?.text ||
  "";

return [
  {
    json: {
      ...formData,
      transcript
    }
  }
];

const raw = $input.first().json;

let formData = {};

try {
  formData = $("Prepare Data With Transcript").first().json;
} catch (error) {
  try {
    formData = $("Prepare Data Without Transcript").first().json;
  } catch (innerError) {
    formData = $("Normalize Form Data").first().json;
  }
}

const content =
  raw.choices?.[0]?.message?.content ||
  raw.message?.content ||
  raw.content ||
  raw.text ||
  "";

let parsed;

try {
  const cleaned = content
    .replace(/```json/g, "")
    .replace(/```/g, "")
    .trim();

  parsed = JSON.parse(cleaned);
} catch (error) {
  parsed = {
    summary: content || "AI response could not be parsed.",
    category: "Other",
    severity: "Medium",
    possible_cause: "",
    suggested_solution: "",
    developer_notes: "Parse error: " + error.message,
    missing_information: "",
    user_reply: ""
  };
}

const allowedCategories = [
  "UI Bug",
  "Backend Bug",
  "Functionality Bug",
  "Performance Bug",
  "Content Bug",
  "Calculation Bug",
  "Configuration Bug",
  "Crash",
  "Frontend",
  "Backend",
  "Auth",
  "Payment",
  "Database",
  "Other"
];

const allowedSeverities = [
  "Low",
  "Medium",
  "High",
  "Critical"
];

const category = allowedCategories.includes(parsed.category)
  ? parsed.category
  : "Other";

const severity = allowedSeverities.includes(parsed.severity)
  ? parsed.severity
  : "Medium";

return [
  {
    json: {
      ...formData,
      ai: {
        summary: parsed.summary || "",
        category,
        severity,
        possible_cause: parsed.possible_cause || "",
        suggested_solution: parsed.suggested_solution || "",
        developer_notes: parsed.developer_notes || "",
        missing_information: parsed.missing_information || "",
        user_reply: parsed.user_reply || ""
      }
    }
  }
];

